// SvelteKit 3 では、プロジェクトの設定をファイル svelte.config.js ではなく、
// Vite のプラグイン sveltekit() の引数に書く (検証の #2)。
// Vitest の設定も、このファイルの項目 test に書く (検証の #4)
import { cloudflareTest, readD1Migrations } from '@cloudflare/vitest-plugin';
import pandacss from '@pandacss/vite';
import { playwright } from '@vitest/browser-playwright';
import adapter from '@sveltejs/adapter-cloudflare';
import { sveltekit } from '@sveltejs/kit/vite';
import { defineConfig } from 'vitest/config';
import { unstable_readConfig } from 'wrangler';
import { budouxWithoutLinkedom } from './scripts/budoux-without-linkedom.ts';
import { wbrAtLineBreaks } from './scripts/svelte-wbr.ts';

// 結合テストで適用する D1 のマイグレーションを、wrangler d1 migrations apply と同じ規則で読む (検証の #9)。
// マイグレーションの置き場と探し方 (項目 migrations_dir・migrations_pattern) は、wrangler.jsonc の
// D1 の binding から読み、このファイルに書き写さない。書き写すと、wrangler.jsonc だけを直したときに、
// 結合テストとデプロイで適用するマイグレーションが変わっても気づけない
async function readMigrationsOfD1Binding(binding: string) {
	const config = unstable_readConfig({ config: './wrangler.jsonc' });
	// wrangler 4.147.0・4.151.1 の型定義は、関数 unstable_readConfig の戻り値の型をパッケージ
	// @cloudflare/workers-utils から import するが、そのパッケージは入っていない (wrangler の中に
	// 同梱されている)。そのため戻り値の型は any になる。使う項目だけに型を付ける
	const d1Databases: { binding: string; migrations_dir?: string; migrations_pattern?: string }[] =
		config.d1_databases;
	const d1 = d1Databases.find((database) => database.binding === binding);
	if (d1 === undefined) {
		throw new Error(`wrangler.jsonc に D1 の binding ${binding} が無い`);
	}
	return readD1Migrations({
		migrationsDir: d1.migrations_dir,
		migrationsPattern: d1.migrations_pattern
	});
}

