		allowedHosts: ['.trycloudflare.com']
	},
	// #100: Vite が依存を前もって束ねる処理は、下の plugins を使わないので、ここにも足す
	optimizeDeps: { rolldownOptions: { plugins: [budouxWithoutLinkedom()] } },
	plugins: [
		// #100: パッケージ budoux が、Worker に linkedom を引き込まないようにする
		budouxWithoutLinkedom(),
		sveltekit({
			compilerOptions: {
				// 依存のパッケージを除き、runes モードで動かす (sv create の雛形のまま)
				runes: ({ filename }) =>
					filename.split(/[/\\]/).includes('node_modules') ? undefined : true
			},
			// Svelte の前処理も、svelte.config.js ではなくここに書く
			preprocess: [wbrAtLineBreaks()],
